package com.privatezero.stadiumpad;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import java.io.*;import java.util.*;import org.json.*;import static com.privatezero.stadiumpad.Data.*;
/** Explicit read-only tablet qualification. Never invokes assignment/EQ/MIDI writes or preset Save. */
public final class ParityInstrumentation extends Instrumentation {
 Bundle args;MainActivity activity;File output;int checks=0;final List<String> passed=new ArrayList<>();
 @Override public void onCreate(Bundle args){super.onCreate(args);this.args=args;start();}
 void check(boolean value,String label)throws Exception{require(value,label);checks++;passed.add(label);}interface Condition{boolean check();}void waitFor(Condition c,String label)throws Exception{long until=SystemClock.elapsedRealtime()+30000;while(SystemClock.elapsedRealtime()<until){if(c.check()){check(true,label);return;}Thread.sleep(50);}throw new IOException("Timed out: "+label+(activity==null?"":" · "+activity.monitor.status+" · "+activity.monitor.workspace.eqMessage+" · "+activity.monitor.workspace.matrixMessage));}
 void screenshot(String name)throws Exception{final Bitmap[] rendered={null};runOnMainSync(()->{View target=name.startsWith("matrix-popup")&&activity.matrixPopup!=null?activity.matrixPopup.content:activity.editor;int width=target.getWidth(),height=target.getHeight();if(width>0&&height>0){Bitmap own=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);target.draw(new Canvas(own));rendered[0]=own;}});Bitmap image=rendered[0]!=null?rendered[0]:getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(output,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 @Override public void onStart(){Bundle result=new Bundle();try{check(ParityTests.verify()>=750,"750+ native schema and routing checks");output=new File(getTargetContext().getExternalFilesDir(null),"parity-verification");output.mkdirs();activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitFor(()->activity.monitor.models.size()>600,"Complete model catalogue loaded");waitFor(()->activity.monitor.workspace.catalog.size()>10,"Command catalogue loaded");
 if(args.getString("mode","readonly").equals("bridge")){File pair=new File(getTargetContext().getExternalFilesDir(null),"pedalbridge-test-private.txt");require(pair.length()>0&&pair.length()<8192,"Missing private test pairing");String link=new String(java.nio.file.Files.readAllBytes(pair.toPath()),"UTF-8");require(pair.delete(),"Remove temporary pairing file");final PedalBridge.Pair parsed=new PedalBridge.Pair(link);runOnMainSync(()->{try{activity.bridgeStore.configure(link);activity.monitor.stop();activity.monitor.connectBridge(parsed);}catch(Exception e){throw new RuntimeException(e);}});}
 waitFor(()->activity.monitor.connected&&activity.monitor.state!=null,"Connected to the real Stadium without writes");int id=activity.monitor.state.id,scene=activity.monitor.state.scene;byte[] preset=activity.monitor.state.bytes.clone();runOnMainSync(()->activity.navigate(3));waitFor(()->activity.monitor.workspace.eq!=null,"Read complete three-output/seven-band EQ");Thread.sleep(250);screenshot("global-eq");runOnMainSync(()->activity.navigate(2));waitFor(()->!activity.monitor.workspace.properties.isEmpty(),"Read Command Center properties");Thread.sleep(250);screenshot("command-center");runOnMainSync(()->activity.matrix());waitFor(()->activity.monitor.workspace.matrix!=null,"Read complete Matrix console");check(activity.monitor.workspace.matrix.strips(1).size()==19,"19 Matrix strips per output");if(activity.monitor.session.bridge!=null)check(activity.monitor.workspace.ready(),"Matrix available through PedalBridge USB");else check(!activity.monitor.workspace.ready()||activity.monitor.workspace.usb.bound(activity.monitor.workspace.device()),"Direct Matrix requires confirmed USB");Thread.sleep(250);screenshot("matrix-popup");runOnMainSync(()->{activity.matrixPopup.home=true;activity.matrixPopup.song=true;activity.matrixPopup.rebuild();activity.matrixPopup.update();});Thread.sleep(200);screenshot("matrix-popup-expanded");
 // Dismiss locally for read-only tests: never use the normal Close action, which mirrors panel navigation.
 runOnMainSync(()->activity.matrixPopup.dialog.dismiss());
 runOnMainSync(()->{try{EditorView original=activity.editor;int saved=original.section;for(int[] size:new int[][]{{1280,800},{1920,1200},{2400,1600}}){EditorView preview=new EditorView(activity,activity.monitor);for(int section:new int[]{0,2,3}){preview.section=section;preview.measure(View.MeasureSpec.makeMeasureSpec(size[0],View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(size[1],View.MeasureSpec.EXACTLY));preview.layout(0,0,size[0],size[1]);Bitmap image=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);preview.draw(new Canvas(image));for(EditorView.Hit hit:preview.hits)if(hit.kind.equals("advanced"))require(hit.rect.left>=0&&hit.rect.right<=preview.W&&hit.rect.top>=0&&hit.rect.bottom<=preview.H,"Advanced control outside viewport: "+hit.label);try(FileOutputStream file=new FileOutputStream(new File(output,"layout-"+size[0]+"-"+section+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,file);}image.recycle();}}}catch(Exception e){throw new RuntimeException(e);}});check(true,"Home, EQ and Command Center fit three tablet viewports");runOnMainSync(()->activity.navigate(0));Thread.sleep(1000);check(activity.monitor.state.id==id&&activity.monitor.state.scene==scene&&Arrays.equals(activity.monitor.state.bytes,preset),"Preset/scene/native bytes unchanged by read-only tests");screenshot("home");result.putInt("checks",checks);result.putString("passed",new JSONArray(passed).toString());result.putBoolean("readOnly",true);finish(-1,result);
 }catch(Throwable e){try{screenshot("failure");}catch(Exception ignored){}result.putInt("checks",checks);result.putString("passed",new JSONArray(passed).toString());result.putString("failure",e.toString());finish(0,result);}}
}
